"""Event catalog — every cross-feature message in one file.

Rules (from docs/06-contracts.md §4):
- Every event is a frozen dataclass with a NAME: ClassVar[str] constant.
- Publishers and subscribers use `Event.NAME` — never a string literal.
- Adding a new event is free. Changing an existing event's shape requires
  updating every publisher and subscriber in the same PR.
- Dead events (no subscribers) must be deleted — they leak coupling.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import ClassVar, Protocol, runtime_checkable

from clara_contracts.briefing import Briefing, Citation
from clara_contracts.feed import FeedCard
from clara_contracts.media import MediaAnalysis
from clara_contracts.persona import PersonaProfile
from clara_contracts.watch import WatchItem


@runtime_checkable
class Event(Protocol):
    """Structural protocol all events satisfy via the NAME ClassVar."""

    NAME: ClassVar[str]


@dataclass(frozen=True, slots=True)
class OnboardingSubmitted:
    NAME: ClassVar[str] = "onboarding.submitted"
    persona_id: str
    situation: str
    city: str
    worry: str
    language_hint: str | None = None


@dataclass(frozen=True, slots=True)
class PersonaPersisted:
    NAME: ClassVar[str] = "persona.persisted"
    profile: PersonaProfile


@dataclass(frozen=True, slots=True)
class CardSelected:
    NAME: ClassVar[str] = "card.selected"
    persona_id: str
    policy_id: str


@dataclass(frozen=True, slots=True)
class BriefingGenerated:
    NAME: ClassVar[str] = "briefing.generated"
    briefing: Briefing


@dataclass(frozen=True, slots=True)
class CitationsResolved:
    NAME: ClassVar[str] = "citations.resolved"
    briefing_id: str
    resolved: list[Citation] = field(default_factory=list)


@dataclass(frozen=True, slots=True)
class VoiceReady:
    NAME: ClassVar[str] = "voice.ready"
    briefing_id: str
    audio_url: str


@dataclass(frozen=True, slots=True)
class MediaAnalyzed:
    NAME: ClassVar[str] = "media.analyzed"
    policy_id: str
    analysis: MediaAnalysis


@dataclass(frozen=True, slots=True)
class WatchlistReady:
    NAME: ClassVar[str] = "watchlist.ready"
    persona_id: str
    items: list[WatchItem] = field(default_factory=list)


@dataclass(frozen=True, slots=True)
class FeedGenerated:
    NAME: ClassVar[str] = "feed.generated"
    persona_id: str
    cards: list[FeedCard] = field(default_factory=list)


@dataclass(frozen=True, slots=True)
class PolicyIngested:
    NAME: ClassVar[str] = "policy.ingested"
    policy_id: str

