def _event_to_wire_payload(event: Event) -> dict[str, Any]:
    """Flatten an event dataclass to a JSON-serializable dict.

    Walks the dataclass ``fields()`` directly rather than using ``asdict``
    because ``asdict`` deep-copies every field — which fails or mangles
    Pydantic v2 ``BaseModel`` instances. Per-field ``_json_safe`` handles
    Pydantic via ``model_dump(mode="json")``.
    """
    if not is_dataclass(event):
        return {"value": str(event)}
    result: dict[str, Any] = {}
    for dc_field in fields(event):
        if dc_field.name == "NAME":
            continue
        result[dc_field.name] = _json_safe(getattr(event, dc_field.name))
    return result

