import type { Config } from "tailwindcss";

// Color tokens locked by docs/01-strategy.md §9 (design language).
// Clara's brutalist-civic palette — do NOT add colors here without updating the
// strategy doc first. Consistency across the UI is what makes the brand legible
// during a 4-minute demo.
export default {
  content: ["./index.html", "./src/**/*.{ts,tsx}"],
  theme: {
    extend: {
      colors: {
        clara: {
          bg: "#0A0E1A",       // Deep blue-black — primary background
          surface: "#111827",  // Elevated surface (cards, sheets)
          border: "#1F2937",   // Hairline dividers
          text: "#E2E8F0",     // Primary text
          muted: "#94A3B8",    // Secondary text
          accent: "#3B82F6",   // Civic blue — primary actions, links, focus
          warning: "#F59E0B",  // Amber — affected groups, watchlist urgency
          success: "#10B981",  // Emerald — reserved for "qualified" states
          danger: "#EF4444",   // Red — reserved for loss-of-rights signals
        },
      },
      fontFamily: {
        sans: ['"Inter"', "ui-sans-serif", "system-ui", "sans-serif"],
        mono: ['"JetBrains Mono"', "ui-monospace", "monospace"],
      },
      borderRadius: {
        card: "0.75rem",
      },
    },
  },
  plugins: [],
} satisfies Config;

// Feature-Sliced Design boundaries enforced by eslint-plugin-boundaries.
//
// Layer rule (strictly downward only):
//   app  →  pages  →  widgets  →  features  →  entities  →  shared
//
// A layer may import FROM lower layers only. Sideways and upward imports are
// lint errors. This file is the static-analysis tripwire for the architecture
// described in docs/03-architecture.md §6 and CLAUDE.md §4.

import js from "@eslint/js";
import tseslint from "@typescript-eslint/eslint-plugin";
import tsparser from "@typescript-eslint/parser";
import boundaries from "eslint-plugin-boundaries";
import reactHooks from "eslint-plugin-react-hooks";
import reactRefresh from "eslint-plugin-react-refresh";

export default [
  { ignores: ["dist", "node_modules", "coverage"] },
  js.configs.recommended,
  {
    files: ["src/**/*.{ts,tsx}"],
    languageOptions: {
      parser: tsparser,
      parserOptions: {
        ecmaVersion: 2022,
        sourceType: "module",
        ecmaFeatures: { jsx: true },
      },
      globals: {
        window: "readonly",
        document: "readonly",
        fetch: "readonly",
        console: "readonly",
      },
    },
    plugins: {
      "@typescript-eslint": tseslint,
      "react-hooks": reactHooks,
      "react-refresh": reactRefresh,
      boundaries,
    },
    settings: {
      "boundaries/include": ["src/**/*"],
      // FSD layer patterns. Single-slice layers (app) match the directory
      // itself; multi-slice layers (pages, features, ...) match one level
      // deep so each slice is its own element of that type.
      "boundaries/elements": [
        { type: "app", pattern: "src/app" },
        { type: "pages", pattern: "src/pages/*" },
        { type: "widgets", pattern: "src/widgets/*" },
        { type: "features", pattern: "src/features/*" },
        { type: "entities", pattern: "src/entities/*" },
        { type: "shared", pattern: "src/shared/*" },
      ],
      // TypeScript-aware resolver so relative imports like `./router`
      // correctly resolve to `router.tsx` and get classified by layer.
      "import/resolver": {
        typescript: {
          project: "./tsconfig.app.json",
        },
      },
    },
    rules: {
      ...reactHooks.configs.recommended.rules,
      "react-refresh/only-export-components": [
        "warn",
        { allowConstantExport: true },
      ],
      // TypeScript handles unused-vars and undef checking. Disable the base
      // ESLint rules — they don't understand TS parameter properties or
      // ambient DOM types, and layering both rules produces false positives.
      "no-unused-vars": "off",
      "no-undef": "off",
      "@typescript-eslint/no-unused-vars": [
        "error",
        { argsIgnorePattern: "^_", varsIgnorePattern: "^_" },
      ],
      "boundaries/element-types": [
        "error",
        {
          default: "disallow",
          rules: [
            {
              from: "app",
              allow: ["pages", "widgets", "features", "entities", "shared"],
            },
            {
              from: "pages",
              allow: ["widgets", "features", "entities", "shared"],
            },
            { from: "widgets", allow: ["features", "entities", "shared"] },
            { from: "features", allow: ["entities", "shared"] },
            { from: "entities", allow: ["shared"] },
            { from: "shared", allow: [] },
          ],
        },
      ],
      "boundaries/no-unknown": "error",
      "boundaries/no-unknown-files": "off",
    },
  },
];

