import { useEffect, useState } from "react";
import { Link } from "react-router-dom";

import { apiClient } from "@shared/api";
import { cn } from "@shared/lib";

type HealthResponse = {
  status: string;
  environment: string;
  features: Record<string, boolean>;
};

export function HomePage() {
  const [health, setHealth] = useState<HealthResponse | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    apiClient
      .get<HealthResponse>("/health")
      .then(setHealth)
      .catch((err: unknown) =>
        setError(err instanceof Error ? err.message : "unknown error"),
      );
  }, []);

  return (
    <main className="mx-auto flex min-h-dvh max-w-3xl flex-col justify-center gap-8 px-6 py-16">
      <header className="flex flex-col gap-3">
        <p className="font-mono text-xs uppercase tracking-widest text-clara-muted">
          TUM.ai × Public Makers · 0.1.0
        </p>
        <h1 className="text-5xl font-semibold leading-tight text-clara-text">
          Clara
        </h1>
        <p className="max-w-prose text-lg text-clara-muted">
          Clara doesn&apos;t fix the laws. It fixes who can access them.
        </p>
      </header>

      <section className="rounded-card border border-clara-border bg-clara-surface p-6">
        <h2 className="mb-3 font-mono text-xs uppercase tracking-widest text-clara-muted">
          Backend status
        </h2>
        {health ? (
          <pre className="overflow-x-auto text-sm text-clara-text">
            {JSON.stringify(health, null, 2)}
          </pre>
        ) : error ? (
          <p className="text-sm text-clara-danger">Cannot reach API: {error}</p>
        ) : (
          <p className="text-sm text-clara-muted">Checking /api/health…</p>
        )}
      </section>

      <Link
        to="/onboarding"
        className={cn(
          "inline-flex w-fit items-center gap-2 rounded-card",
          "bg-clara-accent px-5 py-3 font-medium text-white",
          "transition hover:bg-clara-accent/90",
          "focus:outline-none focus:ring-2 focus:ring-clara-accent focus:ring-offset-2 focus:ring-offset-clara-bg",
        )}
      >
        Start onboarding →
      </Link>
    </main>
  );
}

