1	/**
2	 * Thin fetch wrapper used by every feature.
3	 *
4	 * API_BASE resolution order:
5	 *   1. VITE_API_BASE_URL env var — set this when API and web are on different
6	 *      domains (e.g. Railway: web=clara.up.railway.app, api=clara-api.up.railway.app).
7	 *   2. "/api" fallback — works when both services share the same origin via an
8	 *      nginx/CDN reverse proxy, or when Vite's dev proxy is active.
9	 *
10	 * Never hardcode a backend host in feature code — always go through apiClient.
11	 */
12	
13	const API_BASE: string = import.meta.env.VITE_API_BASE_URL ?? "/api";
14	
15	export class ApiError extends Error {
16	  constructor(
17	    message: string,
18	    public readonly status: number,
19	  ) {
20	    super(message);
21	    this.name = "ApiError";
22	  }
23	}
24	
25	async function request<T>(path: string, init?: RequestInit): Promise<T> {
26	  const res = await fetch(`${API_BASE}${path}`, {
27	    headers: { "Content-Type": "application/json", ...(init?.headers ?? {}) },
28	    ...init,
29	  });
30	  if (!res.ok) {
31	    throw new ApiError(`${res.status} ${res.statusText}`, res.status);
32	  }
33	  if (res.status === 204) {
34	    return undefined as T;
35	  }
36	  return (await res.json()) as T;
37	}
38	
39	export const apiClient = {
40	  get: <T>(path: string) => request<T>(path, { method: "GET" }),
41	  post: <T>(path: string, body: unknown) =>
42	    request<T>(path, { method: "POST", body: JSON.stringify(body) }),
43	};
