/**
 * Thin fetch wrapper used by every feature.
 *
 * API_BASE resolution order:
 *   1. VITE_API_BASE_URL env var — set this when API and web are on different
 *      domains (e.g. Railway: web=clara.up.railway.app, api=clara-api.up.railway.app).
 *   2. "/api" fallback — works when both services share the same origin via an
 *      nginx/CDN reverse proxy, or when Vite's dev proxy is active.
 *
 * Never hardcode a backend host in feature code — always go through apiClient.
 */

const API_BASE: string = import.meta.env.VITE_API_BASE_URL ?? "/api";

export class ApiError extends Error {
  constructor(
    message: string,
    public readonly status: number,
  ) {
    super(message);
    this.name = "ApiError";
  }
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(`${API_BASE}${path}`, {
    headers: { "Content-Type": "application/json", ...(init?.headers ?? {}) },
    ...init,
  });
  if (!res.ok) {
    throw new ApiError(`${res.status} ${res.statusText}`, res.status);
  }
  if (res.status === 204) {
    return undefined as T;
  }
  return (await res.json()) as T;
}

export const apiClient = {
  get: <T>(path: string) => request<T>(path, { method: "GET" }),
  post: <T>(path: string, body: unknown) =>
    request<T>(path, { method: "POST", body: JSON.stringify(body) }),
};

