/**
 * Typed in-process event bus for inter-feature UI coordination.
 *
 * No external dependencies (avoids the mitt RFC). Events that cross the
 * backend boundary arrive via SSE and are forwarded here by the feed feature's
 * SSE bridge.
 *
 * Canonical event shapes come from docs/06-contracts.md §4.2.
 * Adding a new event type requires a §7 RFC.
 */

export type MediaAnalysisPayload = {
  policyId: string;
  officialFraming: string;
  mediaFocus: string;
  hiddenImpact: string;
  watchOutFor: string;
};

export type WatchItemPayload = {
  id: string;
  topic: string;
  nextMilestone: string;
  urgency: "low" | "medium" | "high";
};

export type Span = {
  spanId: string;
  surface: string;
};

/** Canonical map of all frontend bus events. */
export type ClaraEvents = {
  "card.selected": { policyId: string; personaId: string };
  "briefing.ready": { briefingId: string; text: string; spans: Span[] };
  "voice.ready": { briefingId: string; audioUrl: string };
  "citations.resolved": { briefingId: string; resolved: Record<string, string> };
  "media.analyzed": { policyId: string; analysis: MediaAnalysisPayload };
  "watchlist.ready": { personaId: string; items: WatchItemPayload[] };
  "citation.hovered": { spanId: string };
};

type Handler<T> = (payload: T) => void;
type AnyHandler = Handler<unknown>;

class TypedBus<Events extends Record<string, unknown>> {
  private readonly _handlers = new Map<string, Set<AnyHandler>>();

  on<K extends keyof Events & string>(
    event: K,
    handler: Handler<Events[K]>,
  ): () => void {
    let set = this._handlers.get(event);
    if (set === undefined) {
      set = new Set();
      this._handlers.set(event, set);
    }
    set.add(handler as AnyHandler);
    return () => {
      this._handlers.get(event)?.delete(handler as AnyHandler);
    };
  }

  emit<K extends keyof Events & string>(event: K, payload: Events[K]): void {
    this._handlers.get(event)?.forEach((h) => h(payload));
  }

  off<K extends keyof Events & string>(
    event: K,
    handler: Handler<Events[K]>,
  ): void {
    this._handlers.get(event)?.delete(handler as AnyHandler);
  }
}

/** Singleton bus instance shared across all features. */
export const bus = new TypedBus<ClaraEvents>();

