import { useOnboarding } from "../model/useOnboarding";
import { ProgressBar } from "./ProgressBar";
import { QuestionCard } from "./QuestionCard";

const QUESTIONS = [
  {
    field: "situation" as const,
    question: "Tell us about yourself.",
    hint: 'E.g. "Ukrainian refugee, arrived in Munich last year, working part-time."',
  },
  {
    field: "city" as const,
    question: "Which city are you in?",
    hint: 'E.g. "Munich", "Berlin", "Hamburg"',
  },
  {
    field: "worry" as const,
    question: "What is your biggest worry right now?",
    hint: 'E.g. "Renewing my work permit" or "Finding affordable housing"',
  },
] as const;

export function OnboardingFlow() {
  const { state, setAnswer, next, back, submit } = useOnboarding();
  const { step, answers, submitting, error } = state;

  const q = QUESTIONS[step];

  async function handleNext() {
    if (step < 2) {
      next();
    } else {
      await submit();
    }
  }

  return (
    <main className="mx-auto flex min-h-dvh max-w-2xl flex-col justify-center gap-8 px-6 py-16">
      <header className="flex flex-col gap-1">
        <p className="font-mono text-xs uppercase tracking-widest text-clara-muted">
          Clara · Civic Briefing
        </p>
        <h1 className="text-4xl font-semibold text-clara-text">
          Your personalized briefing starts here.
        </h1>
      </header>

      <ProgressBar step={step} />

      <section className="rounded-card border border-clara-border bg-clara-surface p-6">
        <QuestionCard
          key={step}
          question={q.question}
          hint={q.hint}
          value={answers[q.field] ?? ""}
          onChange={(v) => setAnswer(q.field, v)}
          onNext={() => void handleNext()}
          {...(step > 0 ? { onBack: back } : {})}
          isFirst={step === 0}
          isLast={step === 2}
          submitting={submitting}
          error={step === 2 ? error : null}
        />
      </section>

      <p className="text-xs text-clara-muted">
        Your answers never leave your browser until you submit.
      </p>
    </main>
  );
}

