import { KeyboardEvent } from "react";

import { cn } from "@shared/lib";

interface QuestionCardProps {
  question: string;
  hint: string;
  value: string;
  onChange: (value: string) => void;
  onNext: () => void;
  onBack?: () => void;
  isFirst?: boolean;
  isLast?: boolean;
  submitting?: boolean;
  error?: string | null;
}

export function QuestionCard({
  question,
  hint,
  value,
  onChange,
  onNext,
  onBack,
  isFirst = false,
  isLast = false,
  submitting = false,
  error = null,
}: QuestionCardProps) {
  function handleKeyDown(e: KeyboardEvent<HTMLTextAreaElement>) {
    if (e.key === "Enter" && !e.shiftKey && value.trim().length >= 3) {
      e.preventDefault();
      onNext();
    }
  }

  return (
    <div className="flex flex-col gap-6">
      <label htmlFor="onboarding-input" className="text-2xl font-semibold text-clara-text">
        {question}
      </label>

      <textarea
        id="onboarding-input"
        className={cn(
          "min-h-[120px] w-full resize-none rounded-card",
          "border border-clara-border bg-clara-surface",
          "p-4 text-base text-clara-text placeholder:text-clara-muted",
          "focus:border-clara-accent focus:outline-none focus:ring-1 focus:ring-clara-accent",
          "transition-colors duration-150",
        )}
        placeholder={hint}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        onKeyDown={handleKeyDown}
        aria-label={question}
        disabled={submitting}
        autoFocus
      />

      {error !== null && (
        <p role="alert" className="text-sm text-clara-danger">
          {error}
        </p>
      )}

      <p className="text-xs text-clara-muted">Press Enter to continue</p>

      <div className="flex items-center gap-3">
        {!isFirst && onBack !== undefined && (
          <button
            type="button"
            onClick={onBack}
            disabled={submitting}
            className={cn(
              "rounded-card border border-clara-border px-5 py-2.5",
              "text-sm text-clara-muted transition hover:border-clara-accent hover:text-clara-text",
              "focus:outline-none focus:ring-2 focus:ring-clara-accent focus:ring-offset-2",
              "focus:ring-offset-clara-bg",
              "disabled:opacity-40",
            )}
          >
            ← Back
          </button>
        )}

        <button
          type="button"
          onClick={onNext}
          disabled={value.trim().length < 3 || submitting}
          className={cn(
            "rounded-card bg-clara-accent px-5 py-2.5",
            "text-sm font-medium text-white",
            "transition hover:bg-clara-accent/90",
            "focus:outline-none focus:ring-2 focus:ring-clara-accent focus:ring-offset-2",
            "focus:ring-offset-clara-bg",
            "disabled:cursor-not-allowed disabled:opacity-40",
          )}
        >
          {submitting ? "Submitting…" : isLast ? "Get my briefing →" : "Continue →"}
        </button>
      </div>
    </div>
  );
}

