interface ProgressBarProps {
  step: 0 | 1 | 2;
  total?: number;
}

export function ProgressBar({ step, total = 3 }: ProgressBarProps) {
  const current = step + 1;
  const pct = Math.round((current / total) * 100);

  return (
    <div className="flex flex-col gap-2">
      <p className="font-mono text-xs uppercase tracking-widest text-clara-muted">
        Step {current} of {total}
      </p>
      <div
        role="progressbar"
        aria-valuenow={current}
        aria-valuemin={1}
        aria-valuemax={total}
        aria-label={`Step ${current} of ${total}`}
        className="h-0.5 w-full overflow-hidden rounded-full bg-clara-border"
      >
        <div
          className="h-full rounded-full bg-clara-accent transition-all duration-300"
          style={{ width: `${pct}%` }}
        />
      </div>
    </div>
  );
}

