// Onboarding state machine — pure reducer, no framework dependency.
//
// The three steps map directly to the OnboardRequest fields.
// Step 2 (index 2) is the final question; submitting is only possible from there.

export interface OnboardAnswers {
  situation: string;
  city: string;
  worry: string;
  language_hint: string;
}

export interface OnboardingState {
  step: 0 | 1 | 2;
  answers: Partial<OnboardAnswers>;
  submitting: boolean;
  error: string | null;
}

export type OnboardingAction =
  | { type: "SET_ANSWER"; field: keyof OnboardAnswers; value: string }
  | { type: "NEXT" }
  | { type: "BACK" }
  | { type: "SUBMIT_START" }
  | { type: "SUBMIT_ERROR"; message: string }
  | { type: "RESET" };

export const INITIAL_STATE: OnboardingState = {
  step: 0,
  answers: {},
  submitting: false,
  error: null,
};

export function onboardingReducer(
  state: OnboardingState,
  action: OnboardingAction,
): OnboardingState {
  switch (action.type) {
    case "SET_ANSWER":
      return {
        ...state,
        answers: { ...state.answers, [action.field]: action.value },
        error: null,
      };

    case "NEXT":
      if (state.step === 2) return state; // guard: no step beyond 2
      return { ...state, step: (state.step + 1) as 0 | 1 | 2, error: null };

    case "BACK":
      if (state.step === 0) return state; // guard: no step below 0
      return { ...state, step: (state.step - 1) as 0 | 1 | 2, error: null };

    case "SUBMIT_START":
      return { ...state, submitting: true, error: null };

    case "SUBMIT_ERROR":
      return { ...state, submitting: false, error: action.message };

    case "RESET":
      return INITIAL_STATE;

    default:
      return state;
  }
}

