import { useReducer } from "react";
import { useNavigate } from "react-router-dom";

import { postOnboard } from "../api";
import {
  INITIAL_STATE,
  OnboardAnswers,
  OnboardingAction,
  OnboardingState,
  onboardingReducer,
} from "./store";

const PERSONA_ID_KEY = "clara.persona.id";

export interface UseOnboardingReturn {
  state: OnboardingState;
  setAnswer: (field: keyof OnboardAnswers, value: string) => void;
  next: () => void;
  back: () => void;
  submit: () => Promise<void>;
}

export function useOnboarding(): UseOnboardingReturn {
  const [state, dispatch] = useReducer(onboardingReducer, INITIAL_STATE);
  const navigate = useNavigate();

  function setAnswer(field: keyof OnboardAnswers, value: string): void {
    dispatch({ type: "SET_ANSWER", field, value } satisfies OnboardingAction);
  }

  function next(): void {
    dispatch({ type: "NEXT" });
  }

  function back(): void {
    dispatch({ type: "BACK" });
  }

  async function submit(): Promise<void> {
    const { situation, city, worry, language_hint } = state.answers;
    if (!situation || !city || !worry) {
      dispatch({ type: "SUBMIT_ERROR", message: "Please answer all questions." });
      return;
    }

    dispatch({ type: "SUBMIT_START" });

    try {
      const res = await postOnboard({
        situation,
        city,
        worry,
        language_hint: language_hint ?? navigator.language.split("-")[0],
      });

      // Literal implementation of "your profile never leaves your browser"
      localStorage.setItem(PERSONA_ID_KEY, res.persona_id);

      void navigate(`/dashboard?persona=${res.persona_id}`);
    } catch (err) {
      const message = err instanceof Error ? err.message : "Submission failed. Please try again.";
      dispatch({ type: "SUBMIT_ERROR", message });
    }
  }

  return { state, setAnswer, next, back, submit };
}

