// Onboarding does not emit to the FE bus. After submit the flow navigates
// to /dashboard?persona=<id>. The persona_id is persisted to localStorage
// under "clara.persona.id" — that is the "never leaves your browser" contract.
//
// This file is the correct place to add a bus emit if a future feature (e.g.
// a persistent sidebar) needs to react to onboarding completion without
// a full navigation event. Until that need exists, the file stays empty.

export {};

