/**
 * BriefingPanel — renders a full cite-locked briefing.
 *
 * Layout:
 *   1. Opening — warm greeting sentence
 *   2. Paragraphs — each sentence with inline citation anchors
 *   3. Actions — numbered concrete next steps
 *
 * The `spanRenderer` prop follows the render-prop pattern so that F5
 * CitationAnchor can be injected by the widget/dashboard layer without
 * BriefingPanel importing from another feature. The default renderer shows
 * a plain superscript number, keeping the UI useful before F5 ships.
 */

import React from "react";

import type { Briefing } from "../api";
import { ParagraphWithCitations } from "./ParagraphWithCitations";

interface Props {
  briefing: Briefing;
  /** Optional: inject a CitationAnchor from F5. Defaults to plain superscript. */
  spanRenderer?: (spanId: string) => React.ReactNode;
}

function defaultSpanRenderer(spanId: string): React.ReactNode {
  const num = spanId.replace("span_", "");
  return (
    <sup
      className="ml-0.5 text-xs text-clara-accent cursor-default select-none"
      title={spanId}
    >
      [{num}]
    </sup>
  );
}

export function BriefingPanel({
  briefing,
  spanRenderer = defaultSpanRenderer,
}: Props) {
  return (
    <article className="flex flex-col gap-6">
      {/* Opening */}
      <p className="text-lg font-medium text-clara-text">{briefing.opening}</p>

      {/* Paragraphs */}
      <div className="flex flex-col gap-4">
        {briefing.paragraphs.map((para, i) => (
          <ParagraphWithCitations
            key={i}
            text={para.text}
            spanRenderer={spanRenderer}
          />
        ))}
      </div>

      {/* Actions */}
      {briefing.actions.length > 0 && (
        <div
          className="rounded-card border border-clara-border bg-clara-surface p-4"
        >
          <p className="mb-3 text-xs font-mono uppercase tracking-widest text-clara-muted">
            What to do
          </p>
          <ol className="flex list-none flex-col gap-2">
            {briefing.actions.map((action, i) => (
              <li key={i} className="flex gap-2 text-sm text-clara-text">
                <span className="shrink-0 text-clara-accent">
                  {String(i + 1).padStart(2, "0")}
                </span>
                <span>{action}</span>
              </li>
            ))}
          </ol>
        </div>
      )}
    </article>
  );
}

