/**
 * ParagraphWithCitations — renders one briefing paragraph, replacing every
 * [[span_N]] marker with whatever `spanRenderer` returns.
 *
 * Render-prop design: the widget/page layer passes `spanRenderer` so that F5
 * CitationAnchor can be injected without this file importing from another
 * feature (FSD §4.7 compliance). Until F5 ships, the default in BriefingPanel
 * renders a plain superscript number.
 *
 * Span format: [[span_1]], [[span_2]], … — always BEFORE the trailing period.
 */

import React from "react";

interface Props {
  text: string;
  /** Receives the full span ID (e.g. "span_1") and returns a React node. */
  spanRenderer: (spanId: string) => React.ReactNode;
}

export function ParagraphWithCitations({ text, spanRenderer }: Props) {
  // Build a list of {key, node} segments, then render with Fragment keys.
  // A fresh regex per call avoids lastIndex state bugs on rerender.
  const re = /\[\[(span_\w+)\]\]/g;

  const segments: Array<{ key: string; node: React.ReactNode }> = [];
  let lastIndex = 0;
  let match: RegExpExecArray | null;
  let segIndex = 0;

  while ((match = re.exec(text)) !== null) {
    const spanStart = match.index;
    const spanId = match[1] as string; // captured group is always a string

    if (spanStart > lastIndex) {
      segments.push({
        key: `text-${String(segIndex++)}`,
        node: text.slice(lastIndex, spanStart),
      });
    }

    segments.push({
      key: `span-${spanId}-${String(segIndex++)}`,
      node: spanRenderer(spanId),
    });

    lastIndex = spanStart + match[0].length;
  }

  if (lastIndex < text.length) {
    segments.push({
      key: `text-${String(segIndex)}`,
      node: text.slice(lastIndex),
    });
  }

  return (
    <p className="text-clara-text leading-relaxed">
      {segments.map(({ key, node }) => (
        <React.Fragment key={key}>{node}</React.Fragment>
      ))}
    </p>
  );
}

