/**
 * useBriefing — public hook for the Briefing feature.
 *
 * Bus wiring:
 *   card.selected → postTranslate → _setReady → emit briefing.ready
 *
 * The hook subscribes to card.selected once (stable Zustand actions mean the
 * effect only runs on mount). Voice, citations, and other downstream features
 * react to briefing.ready independently.
 */

import { useEffect } from "react";

import { bus } from "@shared/bus";

import { postTranslate } from "../api";
import { useBriefingStore } from "./store";

export function useBriefing() {
  const { status, briefing, error, _setLoading, _setReady, _setError } =
    useBriefingStore();

  useEffect(() => {
    async function handleCardSelected(
      personaId: string,
      policyId: string,
    ): Promise<void> {
      _setLoading();
      try {
        const result = await postTranslate(personaId, policyId);
        _setReady(result);
        bus.emit("briefing.ready", {
          briefingId: result.id,
          text: result.opening,
          // Collect all cited span IDs from paragraphs for downstream features.
          // surface defaults to the raw ID until F5 Citations resolves them.
          spans: result.paragraphs
            .flatMap((p) => p.cited_spans)
            .map((id) => ({ spanId: id, surface: id })),
        });
      } catch (err) {
        const message =
          err instanceof Error ? err.message : "Failed to load briefing.";
        _setError(message);
      }
    }

    const unsub = bus.on("card.selected", ({ personaId, policyId }) => {
      void handleCardSelected(personaId, policyId);
    });

    return unsub;
  }, [_setLoading, _setReady, _setError]);

  return { status, briefing, error };
}

