  /** Transition to "ready" once the briefing is returned. */
  _setReady: (briefing: Briefing) => void;
  /** Transition to "error" if the translate call fails. */
  _setError: (message: string) => void;
  /** Hard reset — e.g. when persona changes. */
  reset: () => void;
