// that it is tied to the component tree that needs briefing data. Emission
// happens inside the same handler, after the translate API call resolves.
//
// This file is the documentation anchor for bus usage. Add emit helpers here
// if a future feature (e.g. an SSE bridge) needs to notify briefing externally.

export {};

