/**
 * CitationAnchor — inline superscript anchor for [[span_N]] markers.
 *
 * Click to open a popover with the resolved citation text and source link.
 * The fetch fires lazily on first click (not on briefing load) so we don't
 * make N requests upfront when a briefing with many citations renders.
 *
 * Injected into BriefingPanel via the `spanRenderer` render prop so that
 * features/briefing never imports from features/citations (FSD §4.7).
 */

import { useState } from "react";

import { useCitation } from "../model/useCitation";
import { CitationPopover } from "./CitationPopover";

interface Props {
  spanId: string;
}

export function CitationAnchor({ spanId }: Props) {
  const [open, setOpen] = useState(false);
  // Fetch lazily: pass spanId only when the popover is open.
  const { loading, citation } = useCitation(open ? spanId : null);

  const num = spanId.replace("span_", "");

  return (
    <span style={{ position: "relative", display: "inline" }}>
      <button
        onClick={() => setOpen((o) => !o)}
        aria-label={`Citation ${num}`}
        aria-expanded={open}
        style={{
          display: "inline",
          background: "transparent",
          border: "none",
          padding: 0,
          cursor: "pointer",
          verticalAlign: "super",
          fontSize: "0.65em",
          color: "#3B82F6",
          fontFamily: "monospace",
          lineHeight: 1,
          marginLeft: "1px",
        }}
      >
        [{num}]
      </button>

      {open && (
        <CitationPopover
          citation={citation}
          loading={loading}
          onClose={() => setOpen(false)}
        />
      )}
    </span>
  );
}

/**
 * CitationPopover — overlay that shows a resolved citation's text and source link.
 *
 * Renders as an absolutely-positioned card beneath the anchor. Inline styles
 * are used for positioning to avoid Tailwind specificity conflicts.
 */

import type { Citation } from "../api";

interface Props {
  citation: Citation | null;
  loading: boolean;
  onClose: () => void;
}

export function CitationPopover({ citation, loading, onClose }: Props) {
  return (
    <div
      role="dialog"
      aria-label="Citation detail"
      style={{
        position: "absolute",
        top: "1.5rem",
        left: "50%",
        transform: "translateX(-50%)",
        zIndex: 50,
        width: "18rem",
        maxWidth: "calc(100vw - 2rem)",
        background: "#111827",
        border: "1px solid #1F2937",
        borderRadius: "0.75rem",
        padding: "0.75rem 1rem",
        boxShadow: "0 8px 32px rgba(0,0,0,0.5)",
      }}
    >
      {/* Close */}
      <button
        onClick={onClose}
        aria-label="Close citation"
        style={{
          position: "absolute",
          top: "0.5rem",
          right: "0.5rem",
          background: "transparent",
          border: "none",
          color: "#94A3B8",
          cursor: "pointer",
          fontSize: "1rem",
          lineHeight: 1,
        }}
      >
        ×
      </button>

      {loading && (
        <p style={{ color: "#94A3B8", fontSize: "0.75rem", margin: 0 }}>
          Resolving…
        </p>
      )}

      {!loading && citation === null && (
        <p style={{ color: "#94A3B8", fontSize: "0.75rem", margin: 0 }}>
          Citation not yet available.
        </p>
      )}

      {!loading && citation !== null && (
        <div style={{ display: "flex", flexDirection: "column", gap: "0.5rem" }}>
          {/* Section label */}
          <p
            style={{
              fontSize: "0.65rem",
              fontFamily: "monospace",
              textTransform: "uppercase",
              letterSpacing: "0.08em",
              color: "#3B82F6",
              margin: 0,
            }}
          >
            {citation.span.surface}
          </p>

          {/* Resolved text */}
          <p
            style={{
              fontSize: "0.8rem",
              color: "#E2E8F0",
              margin: 0,
              lineHeight: 1.5,
            }}
          >
            {citation.resolved_text}
          </p>

          {/* Source link */}
          <a
            href={citation.source_url}
            target="_blank"
            rel="noopener noreferrer"
            style={{
              fontSize: "0.7rem",
              color: "#3B82F6",
              textDecoration: "none",
              wordBreak: "break-all",
            }}
          >
            View source ↗
          </a>
        </div>
      )}
    </div>
  );
}

