/**
 * useCitation — lazy fetch hook for a single citation.
 *
 * Pass `spanId` when you want to fetch, `null` to reset.
 * The fetch fires once on mount (or when spanId changes); a `cancelled` flag
 * prevents stale state updates if the hook re-renders before the call resolves.
 */

import { useEffect, useState } from "react";

import { getCitation } from "../api";
import type { Citation } from "../api";

export type CitationState = {
  loading: boolean;
  citation: Citation | null;
};

export function useCitation(spanId: string | null): CitationState {
  const [state, setState] = useState<CitationState>({
    loading: false,
    citation: null,
  });

  useEffect(() => {
    if (spanId === null) {
      setState({ loading: false, citation: null });
      return;
    }

    setState({ loading: true, citation: null });
    let cancelled = false;

    void (async () => {
      try {
        const citation = await getCitation(spanId);
        if (!cancelled) {
          setState({ loading: false, citation });
        }
      } catch {
        if (!cancelled) {
          setState({ loading: false, citation: null });
        }
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [spanId]);

  return state;
}

