/**
 * F5 Citations — HTTP surface.
 *
 * Types mirror packages/contracts/generated/clara.d.ts (SpanRef, Citation).
 * Inlined here since there is no @contracts path alias in apps/web.
 */

import { ApiError, apiClient } from "@shared/api";

export interface SpanRef {
  span_id: string;
  surface: string;
}

export interface Citation {
  id: string;
  briefing_id: string;
  span: SpanRef;
  resolved_text: string;
  source_url: string;
}

/**
 * Fetch the resolved citation for a single span.
 * Returns null if the span has not been resolved yet (404) — not an error.
 */
export async function getCitation(spanId: string): Promise<Citation | null> {
  try {
    return await apiClient.get<Citation>(
      `/citation/${encodeURIComponent(spanId)}`,
    );
  } catch (err) {
    if (err instanceof ApiError && err.status === 404) return null;
    throw err;
  }
}

