/**
 * VoicePlayer — the "Maria moment" play button.
 *
 * Shows a single play button and a 5-bar CSS waveform.
 * State machine handled by useVoice. No canvas, no audio-analysis libraries.
 *
 * UI states:
 *   idle    — hidden (no briefing selected)
 *   loading — spinner; button disabled
 *   ready   — play button enabled, waveform static
 *   playing — pause icon; waveform animating
 *   ended   — play icon; waveform static (re-playable)
 */

import { useVoice } from "../model/useVoice";
import { WaveformBars } from "./WaveformBars";

type Props = {
  briefingId: string | null;
};

export function VoicePlayer({ briefingId }: Props) {
  const { status, audioUrl, play, audioRef } = useVoice(briefingId);

  if (status === "idle") return null;

  const isPlaying = status === "playing";
  const isLoading = status === "loading";
  const canPlay = status === "ready" || status === "ended";

  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: "12px",
        padding: "12px 16px",
        background: "rgba(59, 130, 246, 0.08)",
        borderRadius: "8px",
        border: "1px solid rgba(59, 130, 246, 0.2)",
      }}
    >
      {/* Hidden audio element — browser handles the chunked mp3 stream */}
      {audioUrl != null && (
        <audio
          ref={audioRef}
          src={audioUrl}
          preload="auto"
          style={{ display: "none" }}
        />
      )}

      {/* Play / loading button */}
      <button
        onClick={canPlay ? play : undefined}
        disabled={!canPlay}
        aria-label={isPlaying ? "Playing" : "Play briefing"}
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          width: "36px",
          height: "36px",
          borderRadius: "50%",
          border: "none",
          background: canPlay ? "#3B82F6" : "rgba(59, 130, 246, 0.3)",
          color: "#fff",
          cursor: canPlay ? "pointer" : "default",
          flexShrink: 0,
        }}
      >
        {isLoading ? (
          <LoadingSpinner />
        ) : isPlaying ? (
          <PauseIcon />
        ) : (
          <PlayIcon />
        )}
      </button>

      {/* Waveform */}
      <WaveformBars isPlaying={isPlaying} />

      {/* Status label */}
      <span
        style={{
          fontSize: "13px",
          color: "#94A3B8",
          userSelect: "none",
        }}
      >
        {isLoading && "Generating audio…"}
        {(status === "ready" || status === "ended") && "Listen to briefing"}
        {isPlaying && "Playing…"}
      </span>
    </div>
  );
}

function PlayIcon() {
  return (
    <svg width="14" height="14" viewBox="0 0 14 14" fill="currentColor">
      <polygon points="2,1 13,7 2,13" />
    </svg>
  );
}

function PauseIcon() {
  return (
    <svg width="14" height="14" viewBox="0 0 14 14" fill="currentColor">
      <rect x="2" y="1" width="4" height="12" />
      <rect x="8" y="1" width="4" height="12" />
    </svg>
  );
}

function LoadingSpinner() {
  return (
    <svg
      width="14"
      height="14"
      viewBox="0 0 14 14"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      style={{ animation: "spin 1s linear infinite" }}
    >
      <circle cx="7" cy="7" r="5" strokeDasharray="20" strokeDashoffset="5" />
      <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
    </svg>
  );
}

