/**
 * WaveformBars — 5-bar CSS-animated waveform.
 *
 * Animates when isPlaying=true, static when false.
 * No canvas, no Web Audio API, no external libraries.
 * Bars are pure CSS keyframe animations with staggered delays.
 */

type Props = {
  isPlaying: boolean;
};

export function WaveformBars({ isPlaying }: Props) {
  return (
    <span
      aria-hidden="true"
      style={{
        display: "inline-flex",
        alignItems: "flex-end",
        gap: "3px",
        height: "20px",
      }}
    >
      {[0, 1, 2, 3, 4].map((i) => (
        <span
          key={i}
          style={{
            display: "block",
            width: "3px",
            backgroundColor: "#3B82F6",
            borderRadius: "2px",
            height: isPlaying ? undefined : "6px",
            minHeight: "4px",
            animation: isPlaying
              ? `waveform-bounce 0.9s ease-in-out ${i * 0.12}s infinite alternate`
              : "none",
          }}
        />
      ))}
      <style>{`
        @keyframes waveform-bounce {
          0%   { height: 4px; }
          50%  { height: 16px; }
          100% { height: 6px; }
        }
      `}</style>
    </span>
  );
}

