/**
 * useVoice — public hook for the VoicePlayer feature.
 *
 * Wires the Zustand store to the FE bus:
 *   briefing.ready  → _setBriefing (transition to "loading")
 *   voice.ready     → _setReady    (transition to "ready", enables play button)
 *
 * Returns the play action and current status for the UI.
 */

import { useEffect, useRef } from "react";
import { bus } from "@shared/bus";
import { useVoiceStore } from "./store";

export function useVoice(briefingId: string | null) {
  const { status, audioUrl, play, onEnded, _setBriefing, _setReady, reset } =
    useVoiceStore();
  const audioRef = useRef<HTMLAudioElement | null>(null);

  // Transition to "loading" when we receive a new briefingId.
  useEffect(() => {
    if (briefingId == null) {
      reset();
      return;
    }
    _setBriefing(briefingId);
  }, [briefingId, _setBriefing, reset]);

  // Subscribe to voice.ready from the backend SSE bridge.
  useEffect(() => {
    const unsubscribe = bus.on("voice.ready", ({ briefingId: id, audioUrl: url }) => {
      _setReady(id, url);
    });
    return unsubscribe;
  }, [_setReady]);

  // When status transitions to "playing", call .play() on the <audio> element.
  useEffect(() => {
    const el = audioRef.current;
    if (el == null) return;
    if (status === "playing") {
      void el.play();
    }
  }, [status]);

  // Wire up the "ended" event from the audio element.
  useEffect(() => {
    const el = audioRef.current;
    if (el == null) return;
    el.addEventListener("ended", onEnded);
    return () => el.removeEventListener("ended", onEnded);
  }, [onEnded]);

  return { status, audioUrl, play, audioRef };
}

