/**
 * Zustand slice for the VoicePlayer feature.
 *
 * State machine: idle → loading → ready → playing → ended
 *
 * idle    — no briefing selected yet
 * loading — briefingId received from briefing.ready, waiting for voice.ready
 * ready   — audioUrl available, play button enabled
 * playing — user pressed play, <audio> element is playing
 * ended   — audio element fired "ended", resets to ready
 */

import { create } from "zustand";

export type VoiceStatus = "idle" | "loading" | "ready" | "playing" | "ended";

type VoiceState = {
  status: VoiceStatus;
  briefingId: string | null;
  audioUrl: string | null;
};

type VoiceActions = {
  /** Called when briefing.ready fires — transitions to "loading". */
  _setBriefing: (briefingId: string) => void;
  /** Called when voice.ready fires — transitions to "ready". */
  _setReady: (briefingId: string, audioUrl: string) => void;
  /** User presses play — transitions to "playing". */
  play: () => void;
  /** Audio element fires "ended" — transitions to "ended" then "ready". */
  onEnded: () => void;
  /** Hard reset — e.g. when a new card is selected. */
  reset: () => void;
};

export type VoiceStore = VoiceState & VoiceActions;

export const useVoiceStore = create<VoiceStore>((set) => ({
  status: "idle",
  briefingId: null,
  audioUrl: null,

  _setBriefing: (briefingId) =>
    set({ status: "loading", briefingId, audioUrl: null }),

  _setReady: (briefingId, audioUrl) =>
    set((s) => {
      // Only accept the ready signal if it matches the currently-loading briefing.
      if (s.briefingId !== briefingId) return s;
      return { status: "ready", audioUrl };
    }),

  play: () =>
    set((s) => {
      if (s.status !== "ready" && s.status !== "ended") return s;
      return { status: "playing" };
    }),

  onEnded: () => set({ status: "ended" }),

  reset: () => set({ status: "idle", briefingId: null, audioUrl: null }),
}));

/**
 * Voice feature API surface.
 *
 * The primary delivery path is GET /api/voice/{briefingId} — a chunked
 * audio/mpeg stream served from the pre-warm cache. The browser <audio>
 * element handles streaming natively; we only need the URL.
 */

export function getVoiceUrl(briefingId: string): string {
  return `/api/voice/${encodeURIComponent(briefingId)}`;
}

/**
 * Watchlist feature · public barrel.
 *
 * The ONLY symbol this feature exposes to the outside world is `WatchList`.
 * Parent layers (pages, widgets) wire it up; other features never import
 * from here (enforced by eslint-plugin-boundaries).
 */

export { WatchList } from "./ui/WatchList";
export type { WatchItem } from "./api";

/**
 * Watchlist feature · list widget-of-the-feature.
 *
 * Public entry point for the slice — the only symbol exported from the
 * barrel index.ts. Takes a `personaId` (from whatever parent decides the
 * active persona) and renders the 3 watch items that the backend produced
 * from the matching `persona.persisted` event.
 *
 * Display states:
 *   - personaId is null       → nothing (hidden until dashboard picks one)
 *   - loading + no items yet  → skeleton row
 *   - error                   → inline error row, non-blocking
 *   - empty (soft-fail path)  → informational "no items yet" row
 *   - populated               → 3 WatchItemCards
 */

import { useWatchlist } from "../model/useWatchlist";
import type { WatchItem as WatchItemType } from "../api";
import { WatchItemCard } from "./WatchItem";

export interface WatchListProps {
  personaId: string | null;
  onAction?: (item: WatchItemType) => void;
}

export function WatchList({ personaId, onAction }: WatchListProps) {
  const { items, loading, error } = useWatchlist(personaId);

  if (!personaId) {
    return null;
  }

  return (
    <section
      aria-labelledby="watchlist-heading"
      className="flex flex-col gap-3"
    >
      <header className="flex items-baseline justify-between">
        <h2
          id="watchlist-heading"
          className="text-sm font-mono uppercase tracking-wider text-slate-400"
        >
          Watch over the next 3 months
        </h2>
        {loading && (
          <span className="text-xs text-slate-500 font-mono">loading…</span>
        )}
      </header>

      {error && (
        <p
          role="alert"
          className="text-xs text-amber-400 font-mono"
        >
          {error}
        </p>
      )}

      {items.length === 0 && !loading && !error && (
        <p className="text-xs text-slate-500 italic">
          No watch items yet. They appear after your persona is built.
        </p>
      )}

      <ul className="flex flex-col gap-3">
        {items.map((item) => (
          <li key={item.id}>
            <WatchItemCard
              item={item}
              {...(onAction !== undefined ? { onAction } : {})}
            />
          </li>
        ))}
      </ul>
    </section>
  );
}

