/**
 * Watchlist feature · React data hook.
 *
 * Contract:
 *   - On mount (or personaId change), issue GET /api/watchlist.
 *   - While mounted, subscribe to `watchlist.ready` on the shared bus and
 *     re-fetch when the backend fires it. This is how F8 updates live after
 *     `persona.persisted` triggers the BE handler — the FE never polls.
 *   - On unmount OR personaId change, unsubscribe and ignore any in-flight
 *     response (stale-closure guard via a local `cancelled` flag).
 *
 * Uses plain useState/useEffect — no TanStack Query. The project ships with
 * Zustand + vanilla React Query-less fetching for day-1 FE per the FE stack
 * decisions in CLAUDE.md §5.2.
 */

import { useCallback, useEffect, useState } from "react";

import { ApiError } from "@shared/api";

import { fetchWatchlist, type WatchItem } from "../api";
import { subscribeWatchlistReady } from "../events";

export interface UseWatchlistState {
  items: WatchItem[];
  loading: boolean;
  error: string | null;
  reload: () => void;
}

export function useWatchlist(personaId: string | null): UseWatchlistState {
  const [items, setItems] = useState<WatchItem[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [refreshToken, setRefreshToken] = useState<number>(0);

  const reload = useCallback(() => {
    setRefreshToken((n) => n + 1);
  }, []);

  useEffect(() => {
    if (!personaId) {
      setItems([]);
      setLoading(false);
      setError(null);
      return;
    }

    let cancelled = false;
    setLoading(true);
    setError(null);

    fetchWatchlist(personaId)
      .then((data) => {
        if (cancelled) return;
        setItems(data);
        setLoading(false);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        const msg =
          err instanceof ApiError
            ? `watchlist ${err.status}`
            : err instanceof Error
              ? err.message
              : "watchlist fetch failed";
        setError(msg);
        setLoading(false);
      });

    const unsubscribe = subscribeWatchlistReady(personaId, reload);

    return () => {
      cancelled = true;
      unsubscribe();
    };
  }, [personaId, refreshToken, reload]);

  return { items, loading, error, reload };
}

