 * Inlined rather than imported because the generated .d.ts has no importable
 * module name — this is the established convention in features/citations and
 * features/briefing.
 *
 * The only backend endpoint F8 exposes:
 *   GET /api/watchlist?persona_id=<id>  →  WatchItem[]
 */

import { apiClient } from "@shared/api";

export type Urgency = "low" | "medium" | "high";

export interface WatchItem {
  id: string;
  persona_id: string;
  topic: string;
  why_it_matters: string;
  current_status: string;
  next_milestone: string;
  urgency: Urgency;
  action_if_passes: string;
  created_at: string;
}

export async function fetchWatchlist(personaId: string): Promise<WatchItem[]> {
  const query = new URLSearchParams({ persona_id: personaId }).toString();
  return apiClient.get<WatchItem[]>(`/watchlist?${query}`);
}

/**
 * Watchlist feature · bus wiring.
 *
 * Cross-feature coordination goes through `@shared/bus` only. Per FSD (and
 * CLAUDE.md §4.7) one feature may not import another — so the bus is how this
 * slice learns that the backend has fired `watchlist.ready` and new items are
 * available to re-fetch.
 *
 * This module does NOT modify the shared bus — it only subscribes. Per the
 * F8 touch-list the shared/bus file is off-limits. The `watchlist.ready`
 * event already exists in the canonical `ClaraEvents` map; we consume it here.
 */

import { bus } from "@shared/bus";

/**
 * Subscribe to `watchlist.ready` for the given personaId.
 *
 * Returns an unsubscribe function for effect cleanup. The event fires after
 * the backend handler persists items — receiving it is the signal that a
 * fresh `GET /api/watchlist` will return populated data (if the handler
 * succeeded) or an empty list (if it soft-failed).
 */
export function subscribeWatchlistReady(
  personaId: string,
  onReady: () => void,
): () => void {
  return bus.on("watchlist.ready", (payload) => {
    if (payload.personaId === personaId) {
      onReady();
    }
  });
}

